steps.script:
# L3-2 (K card worded by reason): the AI deploys both seats of the Ork mirror
# with the gate's attached Wartrikes (same set-up as ai_deploy_p0_legal_formations)
# and is stopped SYNCHRONOUSLY the instant the turn passes to P1 with Warbikers
# Gamma (+ Deffkilla Wartrike Alpha) next: TurnManager emits
# deployment_side_changed inside the action that ends P2's drop, before the AI
# can act for P1. On this board that unit's terrain spots are refused because
# their builds ran out of evaluations ('avoid: budget'), not because nothing
# fits - the case the K card used to call 'no legal set-up fits there'.
for k in ["ai_kcard_reasons_latch", "ai_kcard_reasons_hook", "ai_kcard_reasons_saved"]:
	if GameState.has_meta(k):
		GameState.remove_meta(k)
var gc0 = GameState.state["meta"].get("game_config", null)
GameState.set_meta("ai_kcard_reasons_saved", {"ai_players": AIPlayer.ai_players.duplicate(), "enabled": AIPlayer.enabled,
	"game_config": gc0.duplicate(true) if gc0 is Dictionary else null, "had_game_config": GameState.state["meta"].has("game_config"),
	"speed_preset": AIPlayer._ai_speed_preset, "spectator_index": AIPlayer._spectator_speed_index})
var pairs = {"U_DEFFKILLA_WARTRIKE_A": "U_WARBIKERS_C", "U_DEFFKILLA_WARTRIKE_B": "U_WARBIKERS_D"}
var attached = 0
for cid0 in pairs:
	for sfx in ["", "_P2"]:
		var cid = str(cid0) + sfx
		var bid = str(pairs[cid0]) + sfx
		var bg = GameState.state.units[bid]
		var ad = bg.get("attachment_data", {})
		if ad == null:
			ad = {}
		var lst = ad.get("attached_characters", [])
		if not (cid in lst):
			lst.append(cid)
		ad["attached_characters"] = lst
		bg["attachment_data"] = ad
		GameState.state.units[cid]["attached_to"] = bid
		attached += 1
var hook = func(player):
	if GameState.has_meta("ai_kcard_reasons_latch") or int(player) != 1:
		return
	var und = GameState.get_undeployed_units_for_player(1)
	if und.is_empty() or str(und[0]) != "U_WARBIKERS_C":
		return
	AIPlayer.ai_players = {1: false, 2: false}
	var latch = {"undeployed_p1": und.size(), "digest": DeploymentEval.positions_digest(GameState.state)}
	GameState.set_meta("ai_kcard_reasons_latch", latch)
	print("SCENARIO ai_kcard_reasons latch: P1 next %s, %d P1 units still to deploy" % [str(und[0]), und.size()])
TurnManager.deployment_side_changed.connect(hook)
GameState.set_meta("ai_kcard_reasons_hook", hook)
var gc = GameState.state["meta"].get("game_config", {})
if gc == null:
	gc = {}
gc["player1_type"] = "AI"
gc["player2_type"] = "AI"
GameState.state["meta"]["game_config"] = gc
AIDecisionMaker.set_ai_seed(7)
AIPlayer.configure({1: "AI", 2: "AI"})
# AFTER configure(): it clears plans and profiles.
AIDecisionMaker.clear_all_plans()
AIDecisionMaker._config_overrides["PLANS_ENABLED"] = 0.0
AIPlayer.set_ai_speed_preset(0)
AIPlayer.set_spectator_speed_index(4)
print("SCENARIO ai_kcard_reasons armed: %d attached leaders" % attached)
return "%d|%s" % [attached, str(TurnManager.deployment_side_changed.is_connected(hook))]

# The AI stopped with P1 to move and Warbikers Gamma next, and nothing moved
# since the latch.
var latch = GameState.get_meta("ai_kcard_reasons_latch", {})
var und = GameState.get_undeployed_units_for_player(1)
var ai_on = AIPlayer.is_ai_player(1) or AIPlayer.is_ai_player(2)
var moved = DeploymentEval.positions_digest(GameState.state) != str(latch.get("digest", ""))
return "%d|%d|%s|%s|%s" % [GameState.get_current_phase(), GameState.get_active_player(), str(und[0]) if not und.is_empty() else "-", str(ai_on), str(moved)]

# Hand the board to a local hot-seat human (both seats HUMAN), as in
# ai_suggestion_deployment: the Suggest (K) card is then an AI-reasoning
# inspector for P1's next unit. Plans stay off so the card shows the 11e
# terrain picker's own record.
var h = GameState.get_meta("ai_kcard_reasons_hook", null)
if h != null and TurnManager.deployment_side_changed.is_connected(h):
	TurnManager.deployment_side_changed.disconnect(h)
var gc = GameState.state["meta"].get("game_config", {})
if gc == null:
	gc = {}
gc["player1_type"] = "HUMAN"
gc["player2_type"] = "HUMAN"
GameState.state["meta"]["game_config"] = gc
AIPlayer.configure({1: "HUMAN", 2: "HUMAN"})
AIDecisionMaker.clear_all_plans()
AIDecisionMaker._config_overrides["PLANS_ENABLED"] = 0.0
var main = tree.current_scene
main.refresh_ai_suggestion_button()
AIPlayer.clear_action_log()
return str(main._ai_suggestion_button.visible)

# Diagnostics (debug log): the whole card text, then the unit it is about.
var p = tree.current_scene._ai_suggestion_panel
var bt: String = p.breakdown_text
for line in bt.split("\n"):
	if line.find("not used") >= 0 or line.find("scored higher") >= 0 or line.find("Deploying next") >= 0 or line.find("DEPLOYMENT") >= 0:
		print("SCENARIO ai_kcard_reasons card: %s" % line)
		DebugLogger.info("SCENARIO ai_kcard_reasons card: %s" % line)
return bt.contains("Warbikers Gamma") and bt.contains("== DEPLOYMENT")

# K is a pure preview: nothing was sent and the board is as latched.
var latch = GameState.get_meta("ai_kcard_reasons_latch", {})
var moved = DeploymentEval.positions_digest(GameState.state) != str(latch.get("digest", ""))
return "%d|%s" % [AIPlayer.get_action_log().size(), str(moved)]

# Hygiene: close the card, drop the scenario's meta, and put the AI seats,
# AI speeds, game_config seat types and the plans override back as the
# scenario found them.
var main = tree.current_scene
if main._ai_suggestion_panel != null:
	main._ai_suggestion_panel.hide()
var h = GameState.get_meta("ai_kcard_reasons_hook", null)
if h != null and TurnManager.deployment_side_changed.is_connected(h):
	TurnManager.deployment_side_changed.disconnect(h)
var saved = GameState.get_meta("ai_kcard_reasons_saved", {})
if not saved.is_empty():
	if bool(saved.get("had_game_config", false)) and saved.get("game_config", null) is Dictionary:
		GameState.state["meta"]["game_config"] = saved.get("game_config")
	else:
		GameState.state["meta"].erase("game_config")
	var seats = saved.get("ai_players", {})
	AIPlayer.configure({1: "AI" if bool(seats.get(1, false)) else "HUMAN", 2: "AI" if bool(seats.get(2, false)) else "HUMAN"})
	AIPlayer.enabled = bool(saved.get("enabled", false))
	AIPlayer.set_ai_speed_preset(int(saved.get("speed_preset", 1)))
	AIPlayer.set_spectator_speed_index(int(saved.get("spectator_index", 2)))
AIDecisionMaker._config_overrides.erase("PLANS_ENABLED")
for k in ["ai_kcard_reasons_latch", "ai_kcard_reasons_hook", "ai_kcard_reasons_saved"]:
	if GameState.has_meta(k):
		GameState.remove_meta(k)
var still = h != null and TurnManager.deployment_side_changed.is_connected(h)
return "%s|%s|%s" % [str(still), str(GameState.has_meta("ai_kcard_reasons_latch")), str(AIDecisionMaker._config_overrides.has("PLANS_ENABLED"))]
